import { babel } from '@rollup/plugin-babel';
import terser from '@rollup/plugin-terser';

/*
 * weoc-ui build.
 *
 * Modular ES source (src/) -> one ES5 IIFE that exposes window.WUI, emitted to
 * ../JS/weoc-ui.js — the file boards load from the CDN. That output is
 * GENERATED: never hand-edit it; edit src/ and rebuild. Run from the build/ dir.
 */

const MINIFY = process.env.MINIFY === 'true' || process.env.MINIFY === '1';

const banner =
  '/*! weoc-ui — GENERATED FROM build/src/. DO NOT EDIT THIS FILE.\n' +
  '    Edit the source in build/src/ and run: npm run build */';

export default {
  input: 'src/index.js',
  output: {
    file: MINIFY ? '../JS/weoc-ui.min.js' : '../JS/weoc-ui.js',
    format: 'iife',
    banner,
    sourcemap: true,
  },
  plugins: [
    babel({ babelHelpers: 'bundled' }),
    ...(MINIFY ? [terser({ format: { comments: /^!/ } })] : []),
  ],
};
